// Session Volume Value Model
// Visible-session volume profile: POC + value area expansion, breakout signals.

profileRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessMode = input(true, "Session Mode: Visible Bars")
showHist = input(true, "Show Value Histogram")
showTerrain = input(true, "Show 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ───────────────────────────────────────
sessLen = 120
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 { rng := close * 0.01 }
rowH = rng / profileRows

// ─── Persistent volume-at-price bins ─────────────────────────────
var binVol = array()
if array.size(binVol) == 0 {
    i = 0
    while i < 48 {
        array.push(binVol, 0.0)
        i := i + 1
    }
}

// Clear active rows each bar
i = 0
while i < profileRows {
    array.set(binVol, i, 0.0)
    i := i + 1
}

// Deposit visible-session volume, split proportionally across overlapped rows
j = 0
while j < sessLen {
    bjHigh = high[j]
    bjLow = low[j]
    bjVol = volume[j]
    loRow = floor((bjLow - sessLow) / rng * profileRows)
    hiRow = floor((bjHigh - sessLow) / rng * profileRows)
    if loRow < 0 { loRow := 0 }
    if hiRow > profileRows - 1 { hiRow := profileRows - 1 }
    if loRow > hiRow { tmp = loRow loRow := hiRow hiRow := tmp }
    span = hiRow - loRow + 1
    if span < 1 { span := 1 }
    part = bjVol / span
    if sessMode == false { part := 0.0 }
    k = loRow
    while k <= hiRow {
        array.set(binVol, k, array.get(binVol, k) + part)
        k := k + 1
    }
    j := j + 1
}
// Current bar gets full weight when session mode on (already included as j=0, no extra step)

// ─── Totals + POC ───────────────────────────────────────────────
totalVol = 0.0
i = 0
while i < profileRows {
    totalVol := totalVol + array.get(binVol, i)
    i := i + 1
}
if totalVol <= 0 { totalVol := 1.0 }

pocRow = 0
pocVol = array.get(binVol, 0)
i = 1
while i < profileRows {
    v = array.get(binVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH
pocShare = pocVol / totalVol * 100

// ─── Value area: expand from POC adding higher-volume side first ─
vaLo = pocRow
vaHi = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profileRows {
    leftVal = 0 - 1.0
    if vaLo > 0 { leftVal := array.get(binVol, vaLo - 1) }
    rightVal = 0 - 1.0
    if vaHi < profileRows - 1 { rightVal := array.get(binVol, vaHi + 1) }
    if rightVal >= leftVal and vaHi < profileRows - 1 {
        vaHi := vaHi + 1
        accum := accum + rightVal
    } else {
        if vaLo > 0 {
            vaLo := vaLo - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHi + 1) * rowH
valPrice = sessLow + vaLo * rowH
vaWidth = vahPrice - valPrice
vaMid = (vahPrice + valPrice) / 2
insideVA = close >= valPrice and close <= vahPrice

// Terrain height: price-denominated ridge = POC price lifted by POC dominance
terrainH = pocPrice + pocShare / 100 * rng
if showTerrain == false { terrainH := pocPrice }
// Histogram proxy (2D, separate pane): POC dominance + VA fill ratio
histVal = pocShare
if showHist == false { histVal := histVal * 1.0 }
vaFill = accum / totalVol * 100

