buySig = close[1] <= vahPrice and close > vahPrice
sellSig = close[1] >= valPrice and close < valPrice
pocCrossUp = close[1] <= pocPrice and close > pocPrice
pocCrossDn = close[1] >= pocPrice and close < pocPrice
